const Face* face_for(unsigned pixel_height) noexcept {
    if (pixel_height == 0) return faces;
    const Face* best = faces;
    unsigned best_delta = 0xFFFFFFFFu;
    for (std::size_t i = 0; i < face_count; ++i) {
        const unsigned delta = faces[i].pixel_height > pixel_height
            ? faces[i].pixel_height - pixel_height
            : pixel_height - faces[i].pixel_height;
        if (delta < best_delta) { best_delta = delta; best = &faces[i]; }
    }
    return best;
}

const Glyph* glyph(const Face& face, char ch) noexcept {
    const Glyph* fallback = &face.glyphs[0];
    for (unsigned i = 0; i < face.count; ++i) {
        if (face.glyphs[i].ch == ch) return &face.glyphs[i];
        if (face.glyphs[i].ch == '?') fallback = &face.glyphs[i];
    }
    return fallback;
}
